"""Rebuild the six code-only studies from the unchanged Moon Pool level.
Run from any directory: python3 design/directions/build.py
Only writes the six direction HTML files. Shared styles and compare page are hand-authored.
"""
from pathlib import Path
import json
ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'design/directions'
level = json.loads((ROOT / 'levels/hole05.json').read_text())
points = lambda xy: ' '.join(f'{x},{y}' for x,y in xy)
outer = points(level['walls'][0]['points'])
water = points(level['water'][0]['poly'])
slope = points(level['slopes'][0]['poly'])
styles = {
'afterglow': dict(name='Afterglow',display='unbounded/Unbounded[wght].ttf',body='spacegrotesk/SpaceGrotesk[wght].ttf',turf='#173e43',turf2='#0e272e',wall='#6ef5db',edge='#176879',water='#243cc1',water2='#101c65',slope='#375366',mark='#95c8d3',cup='#071521',accent='#c4ff73',flag='#c4ff73',shadow='#010816',tag='THE NIGHT IS YOURS',tagline='Find your line. Feel the drop.'),
'pocket-park': dict(name='Pocket Park',display='Fredoka-Variable.ttf',body='Nunito-Variable.ttf',turf='#b3d28b',turf2='#87b36f',wall='#faf1d7',edge='#b49a71',water='#64b7c6',water2='#338696',slope='#d6d294',mark='#6c8154',cup='#354b3a',accent='#ad4930',flag='#db6246',shadow='#887653',tag='A LITTLE TIME TO PLAY',tagline='A tiny course. A happy place.'),
'rally-club': dict(name='Rally Club',display='bricolagegrotesque/BricolageGrotesque[opsz,wdth,wght].ttf',body='outfit/Outfit[wght].ttf',turf='#edeaa5',turf2='#d4db7c',wall='#6550cf',edge='#332478',water='#719be3',water2='#4976cb',slope='#eecc83',mark='#92612d',cup='#30226c',accent='#5036b9',flag='#5134bb',shadow='#47308e',tag='GOOD TIMES. GREAT LINES.',tagline='Small course. Big energy.')}
icons = {
'settings':'<path d="M9 4h6l1 3 3 1 1 6-3 2-1 3-6 1-2-3-3-1-1-6 3-2z"/><circle cx="12" cy="12" r="3"/>',
'pause':'<path d="M8 6v12M16 6v12"/>',
'arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>',
'grid':'<rect x="4" y="4" width="6" height="6" rx="2"/><rect x="14" y="4" width="6" height="6" rx="2"/><rect x="4" y="14" width="6" height="6" rx="2"/><rect x="14" y="14" width="6" height="6" rx="2"/>'}
def icon(key):
    return f'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{icons[key]}</svg>'
def head(id,screen,c):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=390, initial-scale=1"><meta name="color-scheme" content="{'dark' if id=='afterglow' else 'light'}"><title>{c['name']} · {screen} · Putt Drop</title><style>@font-face{{font-family:Display;src:url('../../fonts/{c['display']}') format('truetype');font-weight:100 900;font-display:block}}@font-face{{font-family:Body;src:url('../../fonts/{c['body']}') format('truetype');font-weight:100 900;font-display:block}}</style><link rel="stylesheet" href="../screens.css"></head><body class="{id} {screen}"><main class="phone" aria-label="{c['name']} {screen} concept"><div class="status" aria-hidden="true"><span>9:41</span><svg width="66" height="15" viewBox="0 0 66 15" fill="currentColor"><rect x="0" y="9" width="3" height="5" rx="1"/><rect x="5" y="6" width="3" height="8" rx="1"/><rect x="10" y="3" width="3" height="11" rx="1"/><rect x="15" y="0" width="3" height="14" rx="1"/><path d="M25 5q8-7 16 0l-2 2q-6-5-12 0zm4 4q4-4 8 0l-4 4z"/><rect x="46" y="2" width="17" height="11" rx="3" fill="none" stroke="currentColor"/><rect x="48" y="4" width="13" height="7" rx="1"/><rect x="64" y="5" width="2" height="5" rx="1"/></svg></div>'''
def end(): return '<div class="home" aria-hidden="true"></div></main><script src="../screens.js"></script></body></html>'

def hero(id):
    if id=='afterglow':
        art='''<defs><linearGradient id="island" x2="0" y2="1"><stop stop-color="#215664"/><stop offset="1" stop-color="#10282f"/></linearGradient><radialGradient id="pearl" cx=".3" cy=".2"><stop stop-color="#fff"/><stop offset=".7" stop-color="#e2fff2"/><stop offset="1" stop-color="#91bfae"/></radialGradient></defs><g fill="none" stroke="#6ef5db"><ellipse cx="195" cy="150" rx="176" ry="81" opacity=".12"/><ellipse cx="195" cy="150" rx="151" ry="66" opacity=".24" stroke-dasharray="2 9"/></g><path d="M65 155C62 75 197 60 301 122Q347 165 265 207L142 219Q63 213 65 155" fill="#051017" stroke="#173f46" stroke-width="13"/><path d="M65 148C62 68 197 53 301 115Q347 158 265 200L142 212Q63 206 65 148" fill="url(#island)" stroke="#6ef5db" stroke-width="3"/><path d="M83 148Q110 86 220 105T285 164" fill="none" stroke="#91f9dd" stroke-opacity=".18" stroke-width="2"/><ellipse cx="253" cy="153" rx="19" ry="10" fill="#07111c" stroke="#c4ff73" stroke-width="2"/><path d="M253 149v-61" stroke="#c4ff73" stroke-width="2"/><path d="M253 89q22-8 36 5l-36 12" fill="#c4ff73"/><path d="M121 172Q137 132 216 151" fill="none" stroke="#c4ff73" stroke-width="2" stroke-dasharray="3 9"/><g class="idle-ball"><ellipse cx="118" cy="178" rx="21" ry="8" fill="#000" opacity=".3"/><circle cx="118" cy="150" r="22" fill="url(#pearl)"/><circle cx="111" cy="144" r="2" fill="#bddccc"/><circle cx="122" cy="141" r="2" fill="#bddccc"/><circle cx="126" cy="151" r="2" fill="#bddccc"/></g><g fill="#c4ff73"><circle cx="45" cy="74" r="2"/><circle cx="333" cy="198" r="2"/><path d="M322 45v12m-6-6h12" stroke="#c4ff73"/></g>'''
    elif id=='pocket-park':
        art='''<defs><linearGradient id="grass" x2="0" y2="1"><stop stop-color="#badb98"/><stop offset="1" stop-color="#84b475"/></linearGradient><linearGradient id="clay" x2="0" y2="1"><stop stop-color="#fff7dc"/><stop offset="1" stop-color="#d3bf95"/></linearGradient><radialGradient id="pearl" cx=".3" cy=".2"><stop stop-color="#fff"/><stop offset="1" stop-color="#d4d6c1"/></radialGradient></defs><ellipse cx="199" cy="224" rx="144" ry="22" fill="#957e55" opacity=".14"/><path d="M50 148Q54 75 153 91Q226 35 312 110Q361 158 306 211Q273 253 183 227Q72 239 50 178z" fill="#b59e78"/><path d="M50 137Q54 64 153 80Q226 24 312 99Q361 147 306 200Q273 242 183 216Q72 228 50 167z" fill="url(#clay)"/><path d="M65 137Q64 78 158 95Q226 42 301 108Q342 147 294 190Q271 225 184 203Q80 216 65 163z" fill="url(#grass)" stroke="#f7efd2" stroke-width="4"/><path d="M157 95Q184 121 169 149T194 205M212 64Q239 102 223 134T251 212" fill="none" stroke="#fff" stroke-width="26" opacity=".09"/><path d="M207 127Q224 101 254 121T279 163Q251 193 224 165T207 127" fill="#63afba" stroke="#d3e5be" stroke-width="5"/><path d="M227 138q13-8 28 2m-18 9q12-5 19 0" fill="none" stroke="#c6e6dc" stroke-width="2"/><ellipse cx="150" cy="145" rx="12" ry="7" fill="#3a5441"/><path d="M150 144V69" stroke="#685b3e" stroke-width="3"/><path d="M151 69q24-6 35 7l-35 12" fill="#dc6749"/><g class="idle-ball"><ellipse cx="105" cy="180" rx="18" ry="7" fill="#67804e" opacity=".25"/><circle cx="105" cy="166" r="17" fill="url(#pearl)"/></g><g><path d="M303 96V68M82 108V77" stroke="#816b45" stroke-width="6" stroke-linecap="round"/><circle cx="303" cy="58" r="25" fill="#5c8963"/><circle cx="297" cy="50" r="16" fill="#80a776"/><circle cx="82" cy="66" r="22" fill="#80a776"/><circle cx="76" cy="59" r="14" fill="#9abd83"/></g><g fill="#f7edcd"><circle cx="178" cy="191" r="3"/><circle cx="186" cy="187" r="2"/><circle cx="278" cy="110" r="3"/></g>'''
    else:
        art='''<defs><linearGradient id="court" x2="1" y2="1"><stop stop-color="#7856dd"/><stop offset="1" stop-color="#4832a5"/></linearGradient><radialGradient id="pearl" cx=".3" cy=".2"><stop stop-color="#fff"/><stop offset="1" stop-color="#dbdfa7"/></radialGradient></defs><g transform="rotate(-12 195 155)"><rect x="28" y="63" width="334" height="180" rx="90" fill="#d5d78b"/><rect x="25" y="51" width="334" height="180" rx="90" fill="url(#court)"/><rect x="39" y="65" width="306" height="152" rx="76" fill="none" stroke="#b7a1f0" stroke-width="2"/><path d="M103 197V91h43v106m32 0V91h43v106m32 0V91h43v106" stroke="#a68ae9" stroke-width="2" fill="none" opacity=".7"/><path d="M103 172h135" stroke="#eafd83" stroke-width="3" stroke-dasharray="2 9"/><circle cx="276" cy="154" r="20" fill="#25174d" stroke="#eafd83" stroke-width="4"/><path d="M276 150v-64" stroke="#fffbe5" stroke-width="3"/><path d="M278 86h32l-9 13 9 12h-32" fill="#eafd83"/><g class="idle-ball"><ellipse cx="105" cy="176" rx="25" ry="11" fill="#2b1c5c" opacity=".45"/><circle cx="105" cy="151" r="26" fill="url(#pearl)"/><path d="M90 137l10 3m-13 7 10 3m9-17 8 3" stroke="#b5bd8c" stroke-width="2" stroke-linecap="round"/></g></g><g transform="translate(328 44)" stroke="#5036b9" stroke-width="3"><path d="M0-16v32M-16 0h32M-11-11l22 22m0-22-22 22"/></g>'''
    return '<svg class="hero-art" viewBox="0 0 390 280" aria-hidden="true">'+art+'</svg>'
def menu(id,c):
    title = '<span>PUTT</span><span>DROP<span class="logo-dot">.</span></span>' if id=='rally-club' else '<span>Putt</span><span>Drop<span class="logo-dot">.</span></span>'
    return head(id,'menu',c)+f'''<div class="menu-decoration" aria-hidden="true"></div><header class="menu-top"><span class="eyebrow">{c['tag']}</span><button class="icon-button" aria-label="Settings" data-dialog="settings">{icon('settings')}</button></header><div class="brand"><h1>{title}</h1><p>{c['tagline']}</p></div><div class="hero">{hero(id)}</div><div class="menu-footnote"><span class="tiny-dot"></span>{'A quiet kind of electric.' if id=='afterglow' else 'Your own small escape.' if id=='pocket-park' else 'ONE THUMB. ALL FEEL.'}</div><nav class="menu-actions" aria-label="Main menu"><a class="primary" href="play.html"><span><strong>Play</strong><small>Continue · Hole 4</small></span>{icon('arrow')}</a><button class="secondary" data-dialog="holes">{icon('grid')}Holes</button><p class="purchase-note">12 free holes · One unlock for the rest</p></nav>'''+dialogs()+end()
def dialogs():
    return '''<dialog id="settings"><form method="dialog"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h2>Settings</h2><label class="setting">Sound <input type="checkbox" checked></label><label class="setting">Haptics <input type="checkbox" checked></label><button class="primary">Done</button></form></dialog><dialog id="holes"><form method="dialog"><span class="eyebrow">THE FIRST TWELVE ARE FREE</span><h2>Your next round</h2><p>Hole 5 · Moon Pool</p><p>Par 3 · A little water. A lovely bank shot.</p><a class="primary" href="play.html">Explore hole 5</a><button class="secondary">Back</button></form></dialog><dialog id="pause"><form method="dialog"><span class="eyebrow">TAKE YOUR TIME</span><h2>Paused</h2><button class="primary">Resume</button><a class="secondary" href="menu.html">Main menu</a></form></dialog>'''

def course(id,c):
    # All collision silhouettes use the exact source vertices. No smoothing/re-routing.
    polylines=''.join(f'<polyline class="internal-wall" data-wall="{i}" points="{points(w["points"])}" fill="none" stroke="{c["edge"]}" stroke-width="10" stroke-linecap="round"/><polyline points="{points(w["points"])}" fill="none" stroke="{c["wall"]}" stroke-width="6" stroke-linecap="round"/>' for i,w in enumerate(level['walls'][1:],1))
    extra = '<path d="M9 164h9M9 181h9M9 198h9M335 389h12M335 406h12M335 423h12" stroke="currentColor" opacity=".25" stroke-width="2"/>' if id=='rally-club' else ''
    neon = f'<polygon points="{outer}" fill="none" stroke="{c["wall"]}" stroke-opacity=".09" stroke-width="18" stroke-linejoin="round"/>' if id=='afterglow' else ''
    noise = '<pattern id="grain" width="17" height="19" patternUnits="userSpaceOnUse"><circle cx="3" cy="4" r=".7" fill="#fff" opacity=".12"/><circle cx="12" cy="14" r=".6" fill="#102416" opacity=".12"/></pattern>'
    return f'''<svg class="course" viewBox="0 0 360 640" preserveAspectRatio="none" role="img" aria-label="Hole 5, Moon Pool. Par 3. Ball at lower right; cup at upper right. Central water and a slope pointing down and right on the left lane. Aim points up and left at seventy percent power."><defs><linearGradient id="turf" x2="0.7" y2="1"><stop stop-color="{c['turf']}"/><stop offset="1" stop-color="{c['turf2']}"/></linearGradient><linearGradient id="water" x2=".4" y2="1"><stop stop-color="{c['water']}"/><stop offset="1" stop-color="{c['water2']}"/></linearGradient><radialGradient id="ball" cx=".3" cy=".25"><stop stop-color="#ffffff"/><stop offset=".6" stop-color="#f2f7e9"/><stop offset="1" stop-color="#b9cbb8"/></radialGradient><pattern id="mow" width="64" height="64" patternUnits="userSpaceOnUse" patternTransform="rotate(-24)"><rect width="32" height="64" fill="#fff" opacity="{'0.065' if id!='rally-club' else '0.11'}"/></pattern><pattern id="ripples" width="32" height="26" patternUnits="userSpaceOnUse"><path d="M3 12q7-5 14 0t14 0" fill="none" stroke="#e1f9ff" stroke-opacity=".27" stroke-width="1.4"/></pattern><pattern id="slope-pattern" width="26" height="27" patternUnits="userSpaceOnUse" patternTransform="rotate(-11)"><path d="M7 7l7 7H7m7 0V7" fill="none" stroke="{c['mark']}" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></pattern>{noise}<clipPath id="green-clip"><polygon points="{outer}"/></clipPath></defs>{extra}<polygon points="{outer}" transform="translate(0 {'9' if id=='pocket-park' else '5'})" fill="{c['shadow']}" stroke="{c['shadow']}" stroke-width="12" stroke-linejoin="round" opacity=".4"/>{neon}<polygon data-geometry="outer" points="{outer}" fill="url(#turf)" stroke="{c['edge']}" stroke-width="11" stroke-linejoin="round"/><g clip-path="url(#green-clip)"><rect width="360" height="640" fill="url(#mow)"/><rect width="360" height="640" fill="url(#grain)"/><polygon data-geometry="slope" points="{slope}" fill="{c['slope']}" fill-opacity=".75"/><polygon points="{slope}" fill="url(#slope-pattern)"/><polygon data-geometry="water" points="{water}" fill="url(#water)" stroke="{c['edge']}" stroke-width="2" stroke-linejoin="round"/><polygon points="{water}" fill="url(#ripples)"/></g><polygon points="{outer}" fill="none" stroke="{c['wall']}" stroke-width="{'3' if id=='afterglow' else '6'}" stroke-linejoin="round"/>{polylines}<g data-cup="245,165"><circle cx="245" cy="165" r="14" fill="none" stroke="{c['flag']}" stroke-opacity=".24" stroke-width="2"/><circle cx="245" cy="165" r="11" fill="{c['cup']}" stroke="{c['wall']}" stroke-width="1.5"/><path d="M245 162v-43" stroke="{c['wall']}" stroke-width="2"/><path d="M246 120h24l-5 9 5 8h-24" fill="{c['flag']}"/><path d="M250 123h9" stroke="{c['cup']}" stroke-width="1.5"/></g><g class="aim-state"><path d="M245 542L105 474" fill="none" stroke="{c['cup']}" stroke-width="5" stroke-opacity=".2"/><path d="M245 542L105 474" fill="none" stroke="{c['accent']}" stroke-width="3" stroke-dasharray="2 8" stroke-linecap="round"/><path d="M106 483l-7-12 15-1" fill="none" stroke="{c['accent']}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="245" cy="542" r="20" fill="none" stroke="{c['accent']}" stroke-width="1.5" stroke-opacity=".65"/><path d="M254 547l39 19" stroke="{c['accent']}" stroke-opacity=".6" stroke-width="1.5"/><circle cx="303" cy="570" r="10" fill="none" stroke="{c['accent']}" stroke-width="1.5"/><circle cx="245" cy="545" r="8" fill="{c['cup']}" opacity=".3"/><circle data-ball="245,542" cx="245" cy="542" r="7" fill="url(#ball)"/></g></svg>'''
def play(id,c):
    return head(id,'play',c)+f'''<header class="hud"><button class="icon-button" aria-label="Pause" data-dialog="pause">{icon('pause')}</button><div class="hole-title"><span>HOLE 5</span><h1>Moon Pool</h1></div><div class="score"><strong>0 <span>STROKES</span></strong><span>PAR 3</span></div></header><section class="play-area" aria-label="Frozen aim preview">{course(id,c)}<div class="power-panel"><div class="power-caption"><span><i></i>AIMING <b>Release to putt</b></span><strong>70<span>%</span></strong></div><div class="meter" role="meter" aria-label="Shot power" aria-valuemin="0" aria-valuemax="100" aria-valuenow="70"><div></div><span></span></div></div><div class="course-caption">{'FOLLOW THE FEELING' if id=='afterglow' else 'A little nudge goes a long way.' if id=='pocket-park' else 'FIND YOUR LINE.'}</div></section>'''+dialogs()+end()
for id,c in styles.items():
    (OUT/id/'menu.html').write_text(menu(id,c))
    (OUT/id/'play.html').write_text(play(id,c))
print('Built six 390 × 844 HTML screens from levels/hole05.json.')
